import{_ as l,C as s,o as e,c as d,j as i,E as r,a as o,a2 as n}from"./chunks/framework.C21TwvGF.js";const I=JSON.parse(`{"title":"11-dars (Mentor). O'yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar (PNG, SVG)","description":"","frontmatter":{"title":"11-dars (Mentor). O'yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar (PNG, SVG)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":4,"link":"/mentor/9-sinf-game/hafta-04/"},"g":11,"title":"O'yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar (PNG, SVG)","lead":"Yurak belgisini ko'rgan har bir o'yinchi «bu jon» deb biladi — bir so'z ham o'qimasdan. Bugun o'yinlarning «tili» bo'lgan ikonkalar va spraytlar bilan tanishamiz va birinchi ikonkamizni yaratamiz.","slide":"/slaydlar/9-sinf-game/hafta-04/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-04/dars-2-test.html","student_link":"/9-sinf-game/hafta-04/dars-2","tabs":[{"g":10,"link":"/mentor/9-sinf-game/hafta-04/dars-1","current":false},{"g":11,"link":"/mentor/9-sinf-game/hafta-04/dars-2","current":true},{"g":12,"link":"/mentor/9-sinf-game/hafta-04/dars-3","current":false}],"prev":{"g":10,"title":"Ranglar nazariyasi va dizayn asoslari (3-qism): O'yin atmosferasiga mos rang palitrasi yaratish","link":"/mentor/9-sinf-game/hafta-04/dars-1"},"next":{"g":12,"title":"O'yin uchun ikonka va spraytlar yaratish (2-qism): Personaj va obyektlar uchun spraytlar chizish","link":"/mentor/9-sinf-game/hafta-04/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-04/dars-2.md","filePath":"mentor/9-sinf-game/hafta-04/dars-2.md"}`),h={name:"mentor/9-sinf-game/hafta-04/dars-2.md"},k={class:"blk"},g={id:"dars-rejasi",tabindex:"-1"},u={class:"blk"},m={id:"mentor-konspekti",tabindex:"-1"},y={class:"blk"},p={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},b={class:"blk"},f={id:"tezkor-nazorat-savollari",tabindex:"-1"},q={class:"blk"},c={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function v(_,a,x,P,S,G){const t=s("Icon");return e(),d("div",null,[i("div",k,[i("h2",g,[r(t,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga ikonka va sprayt tushunchalari, o&#39;yinlardagi ikonkalar turlari va vazifalari, spraytlardan foydalanish sohalari (personaj, obyekt, fon), rastr va vektor grafika farqi, PNG, SVG va GIF formatlarining xususiyatlari, sprayt va ikonka yaratish vositalari (Photoshop, Aseprite, Piskel) hamda bepul asset kutubxonalari haqida bilim berish; Photoshop&#39;da Custom Shape asosida birinchi vektor ikonkani yaratib, shaffof fonli PNG va SVG qilib eksport qilishni o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar ikonka va spraytni farqlaydi; ikonkaning 6 turini misollar bilan aytadi; vazifaga qarab PNG, SVG yoki GIF ni tanlaydi; Photoshop&#39;da 128×128 px ikonka chizadi va uni shaffof fon bilan PNG ga eksport qiladi; asset kutubxonalaridan foydalanishda litsenziyani tekshirish zarurligini tushunadi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (palitra, kulrang test): 10 daqiqa</li><li>Yangi mavzu: Ikonka va sprayt, turlari va vazifalari: 15 daqiqa</li><li>Rastr va vektor, PNG, SVG, GIF: 15 daqiqa</li><li>Vositalar va bepul kutubxonalar: 10 daqiqa</li><li>Amaliyot: Photoshop&#39;da ikonka yaratish va eksport: 25 daqiqa</li><li>Xulosa: 5 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «O&#39;yin uchun ikonka va spraytlar yaratish» moduli: «Ikonka va spraytlar haqida umumiy tushuncha. Sprayt va ikonka yaratishda dasturiy vositalar. O&#39;yinlardagi ikonkalarning turlari va vazifalari ... Kutubxonalar. Photoshopda ikonkalar. PNG, SVG, GIF formatlari»; o&#39;quv qo&#39;llanma — 2.3-bo&#39;lim (ikonkalar turlari, spraytlar, Aseprite, Piskel, Spine, DragonBones, 2.4-jadval «Spraytlarning bepul kutubxonalari», PNG/SVG/GIF tavsifi, Custom Shape).</p></blockquote><hr>",3))]),i("div",u,[i("h2",m,[r(t,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=n('<h3 id="_1-ikonka-nima" tabindex="-1">1. Ikonka nima? <a class="header-anchor" href="#_1-ikonka-nima" aria-label="Permalink to &quot;1. Ikonka nima?&quot;">​</a></h3><p><strong>Ikonka</strong> — interfeysda obyekt, harakat yoki ma&#39;lumotni ifodalovchi kichik grafik rasm (piktogramma). O&#39;yinda ikonkalar o&#39;yinchiga uzun matnni o&#39;qimasdan tez tushunish va harakat qilish imkonini beradi.</p><p>Nima uchun muhim (o&#39;quv qo&#39;llanma):</p><ul><li><strong>Tez tushunish</strong> — yurak belgisi «jon» ekanini o&#39;yinchi bir zumda biladi.</li><li><strong>Ixchamlik</strong> — murakkab tushuncha kichik joyda ko&#39;rsatiladi.</li><li><strong>Til to&#39;sig&#39;ini kamaytirish</strong> — yaxshi ikonka har qanday tildagi o&#39;yinchiga tushunarli.</li></ul><h3 id="_2-o-yinlardagi-ikonkalar-turlari" tabindex="-1">2. O&#39;yinlardagi ikonkalar turlari <a class="header-anchor" href="#_2-o-yinlardagi-ikonkalar-turlari" aria-label="Permalink to &quot;2. O&#39;yinlardagi ikonkalar turlari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tur</th><th>Vazifasi</th><th>Misol</th></tr></thead><tbody><tr><td><strong>Axborot</strong></td><td>O&#39;yinchi holati yoki dunyo haqida xabar</td><td>jon (yurak), chidamlilik, mini-xarita belgisi</td></tr><tr><td><strong>Interaktiv</strong></td><td>Bosiladigan tugma va elementlar</td><td>do&#39;kon savatchasi, sozlamalar (tishli g&#39;ildirak), pauza</td></tr><tr><td><strong>O&#39;yin (buyum)</strong></td><td>O&#39;yin buyumlari</td><td>qilich, zelye, kalit, tanga</td></tr><tr><td><strong>Uslubiy</strong></td><td>O&#39;yinning vizual uslubini belgilaydi</td><td>minimalistik, realistik, multfilm uslubi</td></tr><tr><td><strong>Bezak</strong></td><td>Funksiyasiz, interfeysni chiroyli qiladi</td><td>ramka burchaklari, yulduzchalar</td></tr><tr><td><strong>Navigatsiya</strong></td><td>Olam yoki menyuda mo&#39;ljal olish</td><td>strelka, kompas, «chiqish» belgisi</td></tr></tbody></table><p>Yaxshi ikonka qoidalari: <strong>oddiy siluyet</strong>, kichik o&#39;lchamda ham tanilishi (32×32 da tekshiring), bitta to&#39;plamda <strong>bir xil uslub, qalinlik va palitra</strong> (10-dars palitrasi).</p><h3 id="_3-sprayt-nima" tabindex="-1">3. Sprayt nima? <a class="header-anchor" href="#_3-sprayt-nima" aria-label="Permalink to &quot;3. Sprayt nima?&quot;">​</a></h3><p><strong>Sprayt</strong> — 2D o&#39;yinda qahramon, obyekt, fon va boshqa elementlarni ifodalovchi ikki o&#39;lchovli tasvir yoki animatsiya. Spraytlar <strong>statik</strong> (tanga, daraxt) yoki <strong>animatsion</strong> (yuruvchi qahramon — bir nechta kadr) bo&#39;ladi.</p><p>Qo&#39;llanish:</p><ul><li><strong>Personajlar</strong> — qahramon va dushmanlar (Super Mario Bros dagi Mario, Luidji);</li><li><strong>Obyektlar</strong> — tanga, qurol, bonus;</li><li><strong>Fon</strong> — daraxt, tog&#39;, bino, taylsetlar.</li></ul><table tabindex="0"><thead><tr><th></th><th>Ikonka</th><th>Sprayt</th></tr></thead><tbody><tr><td>Qayerda</td><td>UI (interfeys) qatlamida</td><td>o&#39;yin olamida</td></tr><tr><td>Vazifa</td><td>ma&#39;lumot berish, bosish</td><td>o&#39;yin obyektini ko&#39;rsatish, harakatlanish</td></tr><tr><td>Animatsiya</td><td>kamdan-kam</td><td>ko&#39;pincha (kadrlar)</td></tr></tbody></table><h3 id="_4-rastr-va-vektor" tabindex="-1">4. Rastr va vektor <a class="header-anchor" href="#_4-rastr-va-vektor" aria-label="Permalink to &quot;4. Rastr va vektor&quot;">​</a></h3><ul><li><strong>Rastr grafika</strong> — piksellardan iborat (Photoshop, Aseprite). Kattalashtirilsa, «zinapoya» va xiralik paydo bo&#39;ladi. Murakkab rangli detallar uchun qulay.</li><li><strong>Vektor grafika</strong> — matematik chiziq va shakllardan iborat (Illustrator, Figma, Photoshop Shape qatlamlari). Istalgan o&#39;lchamga sifat yo&#39;qotmasdan kattalashtiriladi. Oddiy UI ikonkalar uchun qulay.</li></ul><h3 id="_5-formatlar-png-svg-gif" tabindex="-1">5. Formatlar: PNG, SVG, GIF <a class="header-anchor" href="#_5-formatlar-png-svg-gif" aria-label="Permalink to &quot;5. Formatlar: PNG, SVG, GIF&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Format</th><th>Turi</th><th>Shaffoflik</th><th>Animatsiya</th><th>O&#39;yinda qayerda</th></tr></thead><tbody><tr><td><strong>PNG</strong></td><td>rastr, sifatni yo&#39;qotmasdan siqish</td><td>to&#39;liq (alpha kanal)</td><td>yo&#39;q (oddiy PNG)</td><td>qahramon, obyekt, tugmalar, sprayt sheet; Unity, Godot, Unreal yaxshi qo&#39;llab-quvvatlaydi</td></tr><tr><td><strong>SVG</strong></td><td>vektor (matnli XML fayl)</td><td>bor</td><td>(CSS/JS bilan)</td><td>menyu ikonkalari, sozlamalar belgisi, mini-xarita belgilari, veb-o&#39;yinlar UI</td></tr><tr><td><strong>GIF</strong></td><td>rastr, 256 rang</td><td>faqat «bor/yo&#39;q» (yarim shaffof emas)</td><td>bor</td><td>menyudagi kichik animatsiyalar, veb-o&#39;yinlardagi sodda effektlar</td></tr><tr><td>JPG (taqqoslash uchun)</td><td>rastr, sifat yo&#39;qotib siqish</td><td>yo&#39;q</td><td>yo&#39;q</td><td>fotosurat fonlar; sprayt uchun <strong>yaramaydi</strong> (shaffoflik yo&#39;q)</td></tr></tbody></table><p>Asosiy qoida: <strong>sprayt va o&#39;yin ichidagi ikonka → PNG</strong>, <strong>masshtablanadigan UI ikonka → SVG</strong>, <strong>oddiy animatsion belgi → GIF</strong>.</p><h3 id="_6-vositalar" tabindex="-1">6. Vositalar <a class="header-anchor" href="#_6-vositalar" aria-label="Permalink to &quot;6. Vositalar&quot;">​</a></h3><p><strong>Grafik muharrirlar:</strong></p><ul><li><strong>Photoshop</strong> — kuchli rastr muharrir + vektor shakllar; batafsil spraytlar, teksturalar, UI.</li><li><strong>Aseprite</strong> — piksel grafika va animatsiya uchun mashhur (pullik, ochiq kodini o&#39;zi yig&#39;ish mumkin).</li><li><strong>Piskel</strong> — brauzerda ishlaydigan bepul piksel sprayt muharriri (piskelapp.com).</li></ul><p><strong>Animatsiya dasturlari:</strong></p><ul><li><strong>Spine</strong> — skelet (suyak) animatsiyasi, murakkab 2D personajlar uchun;</li><li><strong>DragonBones</strong> — Spine ga o&#39;xshash bepul vosita.</li></ul><h3 id="_7-bepul-asset-kutubxonalari" tabindex="-1">7. Bepul asset kutubxonalari <a class="header-anchor" href="#_7-bepul-asset-kutubxonalari" aria-label="Permalink to &quot;7. Bepul asset kutubxonalari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sayt</th><th>Nima bor</th><th>Formatlar</th></tr></thead><tbody><tr><td>OpenGameArt</td><td>spraytlar, taylsetlar, qahramonlar, fonlar</td><td>PNG, GIF, SVG, ba&#39;zan PSD</td></tr><tr><td>Kenney Assets</td><td>platformer paketlari, UI elementlar</td><td>PNG, SVG, PSD</td></tr><tr><td>CraftPix (Freebies)</td><td>RPG qahramonlar, UI, effektlar</td><td>PNG, PSD</td></tr><tr><td>Itch.io (assets)</td><td>turli mualliflar to&#39;plamlari</td><td>PNG, GIF, PSD</td></tr></tbody></table><p><strong>Muhim:</strong> har bir assetning <strong>litsenziyasini</strong> o&#39;qing (masalan, CC0 — erkin; CC-BY — muallifni ko&#39;rsatish shart). Muallifni ko&#39;rsatmasdan foydalanish — mualliflik huquqini buzish.</p><h3 id="_8-photoshop-da-birinchi-ikonka-128×128-px" tabindex="-1">8. Photoshop&#39;da birinchi ikonka (128×128 px) <a class="header-anchor" href="#_8-photoshop-da-birinchi-ikonka-128×128-px" aria-label="Permalink to &quot;8. Photoshop&#39;da birinchi ikonka (128×128 px)&quot;">​</a></h3><ol><li><strong>File → New</strong>: Width 128, Height 128 px, Resolution 72, Background Contents — <strong>Transparent</strong>.</li><li><strong>Custom Shape Tool</strong> (U, Shape asboblari ichida): yuqori panelda <strong>Shape</strong> rejimi, Shapes ro&#39;yxatidan yurak/yulduz/qalqon shaklini tanlang va chizing (Shift — proporsiya saqlanadi).</li><li><strong>Fill</strong> — 10-dars palitrasidan asosiy rang; <strong>Stroke</strong> — 4 px to&#39;q kontur.</li><li>Hajm berish: yangi qatlam → <strong>Clipping Mask</strong> (Alt + bosish) → yumshoq oq cho&#39;tka bilan yuqori chap tomonga yorug&#39;lik dog&#39;i (yorug&#39;lik manbai — yuqori chapda).</li><li>Kichik o&#39;lchamda tekshirish: <strong>View → 100%</strong> va <code>Image Size</code> nusxasida 32×32 — ikonka hali taniladimi?</li><li><strong>Eksport PNG:</strong> File → Export → <strong>Export As...</strong> → Format: <strong>PNG</strong>, <strong>Transparency</strong> belgilangan → <code>ikon_jon_128.png</code>.</li><li><strong>Eksport SVG:</strong> Shape qatlami ustida o&#39;ng tugma → <strong>Export As...</strong> → SVG (yangi versiyalarda SVG tanlovi bo&#39;lmasa, Illustrator yoki Figma&#39;da qayta chizish tavsiya etiladi).</li></ol><p>Nomlash qoidasi: <code>tur_nom_o&#39;lcham</code> → <code>ikon_tanga_64.png</code>, <code>sprayt_qahramon_idle_32.png</code> (bo&#39;sh joysiz, lotin harflarida).</p><hr>',29))]),i("div",y,[i("h2",p,[r(t,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=n('<h3 id="_1-topshiriq-ikonka-turini-aniqlang-oson" tabindex="-1">1-topshiriq. Ikonka turini aniqlang (oson) <a class="header-anchor" href="#_1-topshiriq-ikonka-turini-aniqlang-oson" aria-label="Permalink to &quot;1-topshiriq. Ikonka turini aniqlang (oson)&quot;">​</a></h3><p>Turini aniqlang: yurak belgisi (jon), tishli g&#39;ildirak (sozlamalar), qilich (inventar), kompas strelkasi, ramka burchagidagi naqsh.</p><p><strong>Yechim:</strong> Yurak — axborot; tishli g&#39;ildirak — interaktiv; qilich — o&#39;yin (buyum); kompas — navigatsiya; naqsh — bezak.</p><h3 id="_2-topshiriq-formatni-tanlang-oson" tabindex="-1">2-topshiriq. Formatni tanlang (oson) <a class="header-anchor" href="#_2-topshiriq-formatni-tanlang-oson" aria-label="Permalink to &quot;2-topshiriq. Formatni tanlang (oson)&quot;">​</a></h3><p>Mos formatni tanlang va sababini ayting: (a) qahramonning shaffof fonli yurish kadrlari; (b) har qanday ekranda keskin ko&#39;rinishi kerak bo&#39;lgan menyu ikonkasi; (c) bosh menyudagi kichik aylanuvchi tanga animatsiyasi (veb-o&#39;yin); (d) fon uchun fotosurat.</p><p><strong>Yechim:</strong> (a) PNG — shaffoflik, sifat, o&#39;yin dvijoklari qo&#39;llaydi; (b) SVG — vektor, sifat yo&#39;qolmaydi; (c) GIF — oddiy animatsiya; (d) JPG (yoki PNG) — fotosurat, shaffoflik kerak emas.</p><h3 id="_3-topshiriq-shaffof-fonli-ikonka-o-rta" tabindex="-1">3-topshiriq. Shaffof fonli ikonka (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-shaffof-fonli-ikonka-o-rta" aria-label="Permalink to &quot;3-topshiriq. Shaffof fonli ikonka (o&#39;rta)&quot;">​</a></h3><p>Photoshop&#39;da 128×128 px shaffof hujjatda «tanga» ikonkasini yarating: doira, kontur, ichida belgi, yorug&#39;lik dog&#39;i. PNG ga eksport qiling.</p><p><strong>Yechim:</strong></p><ol><li>New → 128×128, Transparent.</li><li>Ellipse Tool (U) + Shift: 110×110 doira, Fill <code>#F4C430</code>, Stroke 4 px <code>#8A5A00</code>.</li><li>Ichki kichik doira (Stroke, Fill yo&#39;q) va Text yoki Custom Shape bilan yulduz belgisi.</li><li>Yangi qatlam → Clipping Mask → yuqori chapda oq yumshoq cho&#39;tka (Opacity 40%).</li><li>Export As → PNG, Transparency ✓ → <code>ikon_tanga_128.png</code>. Tekshirish: fayl istalgan fonga qo&#39;yilganda oq to&#39;rtburchak ko&#39;rinmaydi.</li></ol><h3 id="_4-topshiriq-kichik-o-lcham-sinovi-va-to-plam-qiyin" tabindex="-1">4-topshiriq. Kichik o&#39;lcham sinovi va to&#39;plam (qiyin) <a class="header-anchor" href="#_4-topshiriq-kichik-o-lcham-sinovi-va-to-plam-qiyin" aria-label="Permalink to &quot;4-topshiriq. Kichik o&#39;lcham sinovi va to&#39;plam (qiyin)&quot;">​</a></h3><p>Bir uslubdagi 4 ta ikonka to&#39;plamini yarating (jon, tanga, kalit, sozlamalar). Ularni 128, 64 va 32 px o&#39;lchamlarda eksport qiling. Qaysi biri 32 px da yomon taniladi va qanday soddalashtirasiz?</p><p><strong>Yechim:</strong></p><ul><li>Bir xil kontur qalinligi (128 px da 4 px), bir xil yorug&#39;lik yo&#39;nalishi, bitta palitra.</li><li>Export As oynasida Scale (100%, 50%, 25%) yoki Image Size orqali 3 o&#39;lcham.</li><li>Odatda kalit va sozlamalar 32 px da «bo&#39;tqa» bo&#39;ladi: mayda tishlar va detallar olib tashlanadi, siluyet qalinlashtiriladi, kontur 2 px qoldiriladi. Xulosa: ikonka eng kichik o&#39;lchamda ham tanilishi kerak.</li></ul><hr>',15))]),i("div",b,[i("h2",f,[r(t,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=n("<ol><li>Ikonka va sprayt farqi nima? <ul><li><em>Javob:</em> Ikonka — UI dagi ma&#39;lumot/harakat belgisi; sprayt — o&#39;yin olamidagi 2D obyekt yoki personaj (ko&#39;pincha animatsion).</li></ul></li><li>Ikonkalarning 6 turini ayting. <ul><li><em>Javob:</em> Axborot, interaktiv, o&#39;yin (buyum), uslubiy, bezak, navigatsiya.</li></ul></li><li>Nega sprayt uchun JPG yaramaydi? <ul><li><em>Javob:</em> JPG shaffoflikni qo&#39;llamaydi va siqishda sifat yo&#39;qotadi; PNG shaffof va sifatli.</li></ul></li><li>SVG ning asosiy afzalligi nima? <ul><li><em>Javob:</em> Vektor — istalgan o&#39;lchamga sifat yo&#39;qotmasdan kattalashtiriladi, fayl yengil.</li></ul></li><li>Bepul kutubxonadan asset olishda nimani tekshirish shart? <ul><li><em>Javob:</em> Litsenziyani (CC0, CC-BY va h.k.) va muallifni ko&#39;rsatish talabini.</li></ul></li></ol><hr>",2))]),i("div",q,[i("h2",c,[r(t,{name:"file-text"}),a[12]||(a[12]=o(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=n("<ul><li><strong>Oq fon bilan eksport:</strong> hujjat Transparent emas yoki JPG tanlangan — ikonka atrofida oq to&#39;rtburchak paydo bo&#39;ladi.</li><li><strong>Juda ko&#39;p detal:</strong> 128 px da chiroyli, 32 px da tanib bo&#39;lmaydi — siluyetni soddalashtiring.</li><li><strong>Har xil uslub:</strong> bir to&#39;plamda turli kontur qalinligi va yorug&#39;lik yo&#39;nalishi — qoidalarni oldindan belgilang.</li><li><strong>Fayl nomlari:</strong> <code>Untitled-1.png</code>, <code>yangi rasm.png</code> — nomlash qoidasidan foydalaning.</li><li><strong>Litsenziyani o&#39;qimaslik:</strong> kutubxonadagi assetni muallifsiz ishlatish.</li></ul>",1))])])}const T=l(h,[["render",v]]);export{I as __pageData,T as default};
